package edu.campus.rbac;

import edu.campus.rbac.infrastructure.Database;
import edu.campus.rbac.model.Models.*;
import edu.campus.rbac.service.*;
import java.nio.file.*;
import java.util.*;
import org.junit.jupiter.api.*;
import org.junit.jupiter.api.io.TempDir;
import static org.junit.jupiter.api.Assertions.*;

/** 作业验收：全部经过真实 Service、JDBC、SQLite，不用权限模拟。 */
class AcceptanceTest {
    @TempDir static Path temp;
    static Path template;
    Services.Bundle services;
    Path db;
    @BeforeAll static void seed(){template=temp.resolve("template.db");new Database(template).initialize();}
    @BeforeEach void setup()throws Exception{db=temp.resolve(UUID.randomUUID()+".db");Files.copy(template,db);services=ApplicationFactory.open(db);}
    String login(String username){return services.authentication().login(username,"Demo@12345".toCharArray()).token();}
    long role(String token,String code){return services.roles().list(token).stream().filter(r->r.code().equals(code)).findFirst().orElseThrow().id();}
    long user(String token,String name){return services.users().list(token).stream().filter(u->u.username().equals(name)).findFirst().orElseThrow().id();}
    long permission(String token,String code){return services.roles().permissions(token).stream().filter(p->p.code().equals(code)).findFirst().orElseThrow().id();}
    @Test void TC02_adminCanLogin(){Session s=services.authentication().login("admin","Demo@12345".toCharArray());assertTrue(s.permissions().contains("permission:grant"));assertFalse(s.token().isBlank());}
    @Test void TC03to05_viewerCanReadButCannotCreateOrDelete(){String t=login("viewer");List<WorkOrder> before=services.workOrders().list(t,"","");assertFalse(before.isEmpty());assertThrows(DomainException.class,()->services.workOrders().create(t,new WorkOrderInput("拒绝","test")));assertThrows(DomainException.class,()->services.workOrders().delete(t,before.get(0).id()));assertEquals(before,services.workOrders().list(t,"",""));}
    @Test void TC06to07_staffCreatePersistsButCannotDelete(){String t=login("staff");WorkOrder w=services.workOrders().create(t,new WorkOrderInput("维修灯具","教室 A101"));assertThrows(DomainException.class,()->services.workOrders().delete(t,w.id()));Services.Bundle reopened=ApplicationFactory.open(db);String other=reopened.authentication().login("staff","Demo@12345".toCharArray()).token();assertTrue(reopened.workOrders().list(other,"维修灯具","").stream().anyMatch(x->x.id()==w.id()));}
    @Test void TC08to09_managerAssignsButCannotGrant(){String manager=login("manager");long id=services.workOrders().list(manager,"","").get(0).id();User assignee=services.workOrders().assignees(manager).stream().filter(u->u.username().equals("staff")).findFirst().orElseThrow();services.workOrders().assign(manager,id,assignee.id());assertEquals(assignee.id(),services.workOrders().list(manager,Long.toString(id),"").get(0).assigneeId());assertThrows(DomainException.class,()->services.roles().setPermissions(manager,1,Set.of()));}
    @Test void TC10to13_grantAndRevokeApplyToExistingSession(){String a=login("admin"),s=login("staff");long r=role(a,"STAFF"),p=permission(a,"workorder:delete");Set<Long> original=services.roles().permissionIds(a,r);Set<Long> added=new HashSet<>(original);added.add(p);WorkOrder w=services.workOrders().create(s,new WorkOrderInput("临时工单",""));assertThrows(DomainException.class,()->services.workOrders().delete(s,w.id()));services.roles().setPermissions(a,r,added);assertTrue(services.permissions().refresh(s).permissions().contains("workorder:delete"));services.workOrders().delete(s,w.id());WorkOrder next=services.workOrders().create(s,new WorkOrderInput("撤权后保留",""));services.roles().setPermissions(a,r,original);assertThrows(DomainException.class,()->services.workOrders().delete(s,next.id()));assertTrue(services.workOrders().list(s,"撤权后保留","").stream().anyMatch(x->x.id()==next.id()));}
    @Test void TC14_multipleRolesUseUnion(){String a=login("admin");long viewer=user(a,"viewer");services.users().setRoles(a,viewer,Set.of(role(a,"VIEWER"),role(a,"MANAGER")));Session s=services.authentication().login("viewer","Demo@12345".toCharArray());assertTrue(s.permissions().containsAll(Set.of("workorder:list","workorder:assign","report:view")));assertFalse(s.permissions().contains("permission:grant"));}
    @Test void TC15and19_restartPreservesAuthorizationAndWork(){String a=login("admin");long r=role(a,"STAFF"),p=permission(a,"workorder:create");Set<Long> ids=new HashSet<>(services.roles().permissionIds(a,r));ids.remove(p);services.roles().setPermissions(a,r,ids);WorkOrder w=services.workOrders().create(a,new WorkOrderInput("持久化证据","内容"));Services.Bundle next=ApplicationFactory.open(db);String s=next.authentication().login("staff","Demo@12345".toCharArray()).token();assertFalse(next.permissions().refresh(s).permissions().contains("workorder:create"));assertTrue(next.workOrders().list(s,"持久化证据","").stream().anyMatch(x->x.id()==w.id()));}
    @Test void TC16and17_forbiddenRoleAndPageAccess(){String s=login("staff");assertThrows(DomainException.class,()->services.users().setRoles(s,3,Set.of(1L)));assertThrows(DomainException.class,()->services.permissions().require(s,"page:users:view"));assertThrows(DomainException.class,()->services.roles().setPermissions(s,3,Set.of()));}
    @Test void TC18_successAndDenialAreAudited(){String a=login("admin"),v=login("viewer");WorkOrder w=services.workOrders().create(a,new WorkOrderInput("审计证据",""));assertThrows(DomainException.class,()->services.workOrders().delete(v,w.id()));List<AuditEntry> logs=services.audit().list(a,"");assertTrue(logs.stream().anyMatch(x->x.action().equals("workorder:create")));assertTrue(logs.stream().anyMatch(x->x.action().equals("workorder:delete")&&Objects.equals(x.actorId(),user(a,"viewer"))));}
    @Test void forgedAndLoggedOutTokensCannotAct(){assertThrows(DomainException.class,()->services.workOrders().list("1","",""));String token=login("admin");services.authentication().logout(token);assertThrows(DomainException.class,()->services.workOrders().create(token,new WorkOrderInput("不能创建","")));}
    @Test void workOrderLifecycleAndLiteralSearch(){String a=login("admin");WorkOrder w=services.workOrders().create(a,new WorkOrderInput("100% _ ' 测试","多行\n内容"));services.workOrders().update(a,w.id(),new WorkOrderInput("已更新","详情"));services.workOrders().changeStatus(a,w.id(),"处理中");assertTrue(services.workOrders().list(a,"已更新","处理中").stream().anyMatch(x->x.id()==w.id()));assertTrue(services.workOrders().list(a,"' OR 1=1 --","").isEmpty());assertThrows(DomainException.class,()->services.workOrders().changeStatus(a,w.id(),"非法"));services.workOrders().delete(a,w.id());assertTrue(services.workOrders().list(a,"已更新","").isEmpty());}
    @Test void csvEscapesQuotesNewlinesAndFormulas(){String a=login("admin");services.workOrders().create(a,new WorkOrderInput("=SUM(1,2)","带\"引号\"\n换行"));String csv=services.workOrders().exportCsv(a,"=SUM","");assertTrue(csv.contains("\"'=SUM(1,2)\""));assertTrue(csv.contains("带\"\"引号\"\"\n换行"));assertThrows(DomainException.class,()->services.workOrders().exportCsv(login("viewer"),"",""));}
    @Test void statisticsMatchDatabase(){String a=login("admin");Statistics stats=services.reports().statistics(a);assertEquals(services.workOrders().list(a,"","").size(),stats.total());assertEquals(stats.total(),stats.byStatus().values().stream().mapToLong(Long::longValue).sum());assertThrows(DomainException.class,()->services.reports().statistics(login("staff")));}
    @Test void referencedUserDeletionPreservesHistory(){String a=login("admin");User u=services.users().create(a,"temporary","临时人员","Temp@12345".toCharArray());services.users().setRoles(a,u.id(),Set.of(role(a,"STAFF")));String t=services.authentication().login("temporary","Temp@12345".toCharArray()).token();WorkOrder w=services.workOrders().create(t,new WorkOrderInput("历史保留",""));services.users().delete(a,u.id());WorkOrder persisted=services.workOrders().list(a,"历史保留","").get(0);assertEquals(w.id(),persisted.id());assertEquals(0,persisted.creatorId());assertThrows(DomainException.class,()->services.workOrders().list(t,"",""));}
}
